export const RTL_LANGS = ['dari', 'urdu', 'pashto'];
export function getLang() { try { return localStorage.getItem('bmcc_lang') || 'en'; } catch (e) { return 'en'; } }
export function setLang(code) { try { localStorage.setItem('bmcc_lang', code); } catch (e) {} }
export function isRTL(code) { return RTL_LANGS.includes(code); }

